let harness: MongoReplicaSetHarness, server: Server, base = '', token = '', userToken = '';
const actor = new ObjectId(), other = new ObjectId(), user = new ObjectId(), album = new ObjectId(), artist = new ObjectId(), first = new ObjectId(), second = new ObjectId();
const db = () => getDb()!, mutation = (revision: number) => ({ operationId: randomUUID(), expectedRevision: revision });
const code = (expected: string) => (error: any) => error.code === expected;
const albumTitle: CatalogReviewField = { scope: 'album', slotId: null, field: 'title' };
const provider: ImportAnalysisProvider = { configured: () => true, analyze: async input => input.album ? [{ scope: 'album', slotId: null, field: 'title', baseline: input.baseline.album.title, value: 'Proposed Album', source: 'context', evidence: 'Existing title' }] : [] };
const deferred = () => { let resolve!: () => void; const promise = new Promise<void>(r => { resolve = r; }); return { resolve, promise }; };
const createBody = async () => ({ operationId: randomUUID(), albumId: String(album), expectedRevision: adminCatalogItemRevision('album', await db().collection('albums').findOne({ _id: album })) });
const create = async () => createCatalogReview(String(actor), await createBody());
const current = (id: string) => getCatalogReview(String(actor), id);
const edit = (result: CatalogReviewResponse, change: (draft: CatalogReviewResponse['item']['draft']) => void) => { const draft = structuredClone(result.item.draft); change(draft); return editCatalogReview(String(actor), result.item.id, { ...mutation(result.item.revision), draft }); };
const apply = (result: CatalogReviewResponse, fields: CatalogReviewField[] = [albumTitle]) => applyCatalogReview(String(actor), result.item.id, { ...mutation(result.item.revision), fields });
type Change = { path: string; base: unknown; value: unknown };
/** A per-path review save of `changes`, at the review's revision unless another is given. */
const save = (result: CatalogReviewResponse, changes: Change[], revision = result.item.revision) => editCatalogReview(String(actor), result.item.id, { ...mutation(revision), changes });
/**
 * Admits a review to metadata lookup as a lookup request does: the conversion and a write guarded by the revision it read, in one
 * transaction. A conversion advances the revision itself; a check leaves it.
 */
const admitLookup = (id: string) => withImportAdmin(String(actor), async session => {
    const doc = (await importCollection().findOne({ _id: new ObjectId(id) }, { session }))!, observed = doc.revision;
    await catalogReviewForLookup(doc, session);
    assert.equal((await importCollection().replaceOne({ _id: doc._id, revision: observed }, doc, { session })).matchedCount, 1);
});
const request = (path: string, method = 'GET', body?: unknown, access = token, viewer?: string) => fetch(base + '/api/admin/v1' + path, { method, headers: { ...(access ? { Authorization: `Bearer ${access}` } : {}), 'Content-Type': 'application/json', ...(viewer ? { 'X-Finitude-Account-Viewer': viewer } : {}) }, ...(body === undefined ? {} : { body: JSON.stringify(body) }) });
before(async () => {
    harness = await startMongoReplicaSet('archtree-catalog-review-test');
    for (const index of adminImportIndexes) await db().collection(index.collection).createIndex(index.keys, index.options);
    server = await new Promise(resolve => { const active = createApp().listen(0, '127.0.0.1', () => resolve(active)); });
    const address = server.address(); assert.ok(address && typeof address !== 'string'); base = `http://127.0.0.1:${address.port}`;
});
beforeEach(async () => {
    for (const name of ['users', 'authSessions', 'adminAlbumImports', 'adminImportAnalysisSlots', 'albums', 'artists', 'audioTracks', 'organizations']) await db().collection(name).deleteMany({});
    process.env.FINITUDE_ADMIN_IMPORTS_ENABLED = 'true';
    const account = { _id: actor, email: 'review-admin@example.test', emailVerified: true, role: 'admin' }, ordinary = { _id: user, email: 'review-user@example.test', emailVerified: true, role: 'user' };
    await db().collection('users').insertMany([account, ordinary, { _id: other, role: 'admin' }]);
    token = (await createSession(account)).accessToken; userToken = (await createSession(ordinary)).accessToken;
    await db().collection('artists').insertOne({ _id: artist, name: 'Existing Artist', lifecycleStatus: 'ready', visibility: 'hidden' });
    await db().collection('albums').insertOne({ _id: album, title: 'Existing Album', releaseDate: { year: 2020 }, visibility: 'hidden', lifecycleStatus: 'ready', audioTrackIds: [String(first), String(second)], credits: [{ creditId: 'primary_artist', subjectType: 'artist', subjectId: String(artist), role: 'primary', order: 0 }], attributionStatus: 'documented', coverArtUrl: 'unchanged', unrelated: 'retained' });
    await db().collection('audioTracks').insertMany([first, second].map((id, index) => ({ _id: id, title: `Track ${index + 1}`, originalFileName: index ? undefined : '01 - Original.mp3', trackNumber: index + 1, uploadStatus: 'ready', publicationStatus: 'ready', s3Key: String(id), albumId: String(album), visibility: 'public', mediaType: 'audio', duration: '1:00', unrelated: 'retained' })));
    await initializeAdminImportStorage(db());
});
after(async () => { await new Promise<void>(resolve => server?.close(() => resolve())); await harness?.stop(); delete process.env.FINITUDE_ADMIN_IMPORTS_ENABLED; });

test('private routing rejects anonymous, ordinary users and mismatched viewer before body; current admin reads shared reviews', async () => {
    const body = await createBody();
    assert.equal((await request('/catalog-reviews', 'POST', body, '')).status, 401);
    assert.equal((await request('/catalog-reviews', 'POST', body, userToken)).status, 403);
    assert.equal((await fetch(base + '/api/admin/v1/catalog-reviews', { headers: { Cookie: `session_token=${token}`, 'X-Finitude-Account-Viewer': String(other) } })).status, 409);
    assert.equal((await fetch(base + '/api/admin/v1/catalog-reviews', { method: 'POST', headers: { Authorization: `Bearer ${userToken}`, 'Content-Type': 'application/json' }, body: '{broken' })).status, 403);
    const admitted = await request('/catalog-reviews', 'POST', body); assert.equal(admitted.status, 201); assert.match(admitted.headers.get('cache-control')!, /no-store/);
    const value = await admitted.json(); assert.equal(value.item.sourceStatus, 'current');
    const wire = JSON.stringify(value); for (const forbidden of ['s3Key', 'actorId', 'bucket', 'coverArtUrl', 'unrelated']) assert.equal(wire.includes(forbidden), false);
    assert.equal((await getCatalogReview(String(other), value.item.id)).item.startedByMe, false);
    await db().collection('users').updateOne({ _id: actor }, { $set: { role: 'user' } });
    assert.equal((await request(`/catalog-reviews/${value.item.id}`)).status, 403);
});
test('source snapshot retains actual names and missing naming evidence; create receipt replays across source changes', async () => {
    const body = await createBody(), a = await createCatalogReview(String(actor), body);
    // The Album's Credits become read-only context; each Track captures its Disc Number (null: none stored).
    assert.deepEqual(a.item.draft.album.artists, [{ key: derivedEntryKey({ catalogReview: a.item.id, creditId: 'primary_artist' }), name: 'Existing Artist', role: 'primary', joinPhrase: null, musicBrainzId: null }]);
    assert.equal(a.item.draft.album.label, null);
    assert.deepEqual(a.item.source.tracks.map(track => [track.originalFileName, track.discNumber]), [['01 - Original.mp3', null], [null, null]]);
    assert.deepEqual(a.item.draft.tracks.map(track => track.discNumber), [null, null]);
    const stored = await importCollection().findOne({ _id: new ObjectId(a.item.id) });
    assert.equal(stored!.manifest.rootLabel, ''); assert.deepEqual(stored!.manifest.files.map(file => file.relativePath), ['', '']);
    await db().collection('albums').updateOne({ _id: album }, { $set: { title: 'Changed' } });
    const replay = await createCatalogReview(String(actor), body); assert.equal(replay.item.id, a.item.id); assert.equal(replay.item.sourceStatus, 'changed'); assert.equal(replay.item.capabilities.apply, false);
    await assert.rejects(createCatalogReview(String(actor), { ...body, albumId: String(first) }), code('ADMIN_IMPORT_OPERATION_CONFLICT'));
});
test('zero-track Album supports metadata-only review; malformed, excessive, mixed Video and unavailable membership fail closed', async () => {
    await db().collection('albums').updateOne({ _id: album }, { $set: { audioTrackIds: [] } });
    const empty = await create(); assert.deepEqual(empty.item.source.tracks, []);
    await analyzeCatalogReview(String(actor), empty.item.id, mutation(1), provider);
    await runAdminImportWorkerOnce(provider); assert.equal((await current(empty.item.id)).item.analysis.state, 'complete');
    for (const audioTrackIds of [[String(first), String(first)], ['bad'], Array.from({ length: 101 }, () => String(new ObjectId()))]) {
        await db().collection('albums').updateOne({ _id: album }, { $set: { audioTrackIds } });
        await assert.rejects(create(), code('ADMIN_CATALOG_REVIEW_MEMBERSHIP_UNAVAILABLE'));
    }
    await db().collection('albums').updateOne({ _id: album }, { $set: { audioTrackIds: [String(first), String(second)] } });
    await db().collection('audioTracks').updateOne({ _id: second }, { $set: { mediaType: 'video', s3Key: `video/${second}/${new ObjectId()}` } });
    await assert.rejects(create(), code('ADMIN_CATALOG_REVIEW_SOURCE_CHANGED'));
    await db().collection('audioTracks').updateOne({ _id: second }, { $set: { mediaType: 'audio', s3Key: String(second), publicationStatus: 'pending' } });
    await assert.rejects(create(), code('ADMIN_CATALOG_REVIEW_SOURCE_CHANGED'));
});
test('review projects never enter legacy import inventory/read/mutations/asset/duplicate/publication protocols', async () => {
    const review = await create(), id = review.item.id, slotId = review.item.source.tracks[0].slotId;
    const legacy = await createAdminImport(String(actor), { operationId: randomUUID(), manifest: { rootLabel: 'Folder', files: [{ slotId: randomUUID(), filename: 'Song.mp3', relativePath: 'Song.mp3', byteLength: 10 }] } });
    const imports = await listAdminImports(String(actor), {}); assert.equal(imports.counts.all, 1); assert.deepEqual(imports.items.map(row => row.id), [legacy.item.id]);
    const reviews = await listCatalogReviews(String(actor), {}); assert.equal(reviews.counts.all, 1); assert.equal(reviews.items[0].id, id);
    await assert.rejects(getCatalogReview(String(actor), legacy.item.id), code('ADMIN_CATALOG_REVIEW_NOT_FOUND'));
    for (const call of [() => getAdminImport(String(actor), id), () => editAdminImport(String(actor), id, { ...mutation(1), draft: review.item.draft }), () => analyzeAdminImport(String(actor), id, mutation(1), provider), () => cancelAdminImportAnalysis(String(actor), id, mutation(1)), () => adoptAdminImportSuggestions(String(actor), id, { ...mutation(1), generation: 0, selectedIds: [String(first)], rejectIds: [] }), () => adminImportDuplicateCandidates(String(actor), id), () => decideAdminImportDuplicates(String(actor), id, { ...mutation(1), decisions: [] }), () => publishAdminImport(String(actor), id, mutation(1)), () => selectAdminImportCover(String(actor), id, { ...mutation(1), slotId: null }), () => cleanupAdminImportAsset(String(actor), id, slotId, mutation(1))]) await assert.rejects(call, code('ADMIN_IMPORT_NOT_FOUND'));
    await assert.rejects(previewAdminImportAsset(String(actor), id, 'cover'), code('ADMIN_IMPORT_ASSET_NOT_FOUND'));
    await assert.rejects(resumeAdminImportPublication(String(actor), id, randomUUID()), code('ADMIN_IMPORT_PUBLICATION_CONFLICT'));
    await assert.rejects(cancelAdminImportPublication(String(actor), id, { ...mutation(1), publicationOperationId: randomUUID() }), code('ADMIN_IMPORT_NOT_FOUND'));
    let put = 0; const storage = { put: async () => { put++; throw new Error(); } } as unknown as ImportObjectStorage;
    process.env.FINITUDE_ADMIN_IMPORT_PRIVATE_STORAGE_READY = 'true';
    try { await assert.rejects(uploadAdminImportAsset(String(actor), id, slotId, mutation(1), { size: 1, mimetype: 'audio/mpeg', originalname: 'Song.mp3', buffer: Buffer.from('x') } as Express.Multer.File, storage), code('ADMIN_IMPORT_NOT_FOUND')); } finally { process.env.FINITUDE_ADMIN_IMPORT_PRIVATE_STORAGE_READY = 'false'; }
    assert.equal(put, 0); assert.equal((await current(id)).item.revision, 1);
});
test('source status distinguishes changed metadata and unavailable lifecycle and prevents apply without blocking private draft repair', async () => {
    let review = await create(); await db().collection('audioTracks').updateOne({ _id: first }, { $set: { title: 'External edit' } });
    review = await current(review.item.id); assert.equal(review.item.sourceStatus, 'changed'); assert.equal(review.item.capabilities.apply, false);
    review = await edit(review, draft => { draft.album.title = 'Private correction'; });
    await assert.rejects(apply(review), code('ADMIN_CATALOG_REVIEW_SOURCE_CHANGED'));
    await db().collection('albums').updateOne({ _id: album }, { $set: { lifecycleStatus: 'deleting' } });
    assert.equal((await current(review.item.id)).item.sourceStatus, 'unavailable');
});
test('legacy file replacement without metadata revision change invalidates filename evidence and apply', async () => {
    for (const replacement of [{ originalFileName: '02 - Different.mp3' }, { s3Key: `audio/${first}/${new ObjectId()}` }]) {
        const review = await create();
        const before = adminCatalogItemRevision('audioTrack', await db().collection('audioTracks').findOne({ _id: first }));
        await db().collection('audioTracks').updateOne({ _id: first }, { $set: replacement });
        assert.equal(adminCatalogItemRevision('audioTrack', await db().collection('audioTracks').findOne({ _id: first })), before);
        assert.equal((await current(review.item.id)).item.sourceStatus, 'changed');
        await assert.rejects(apply(review), code('ADMIN_CATALOG_REVIEW_SOURCE_CHANGED'));
    }
});
test('manual edit and provider checkpoint preserve baseline conflict; individual adoption changes only private saved values', async () => {
    let review = await create(); review = await analyzeCatalogReview(String(actor), review.item.id, mutation(1), provider);
    review = await edit(review, draft => { draft.album.title = 'Manual correction'; });
    await runAdminImportWorkerOnce(provider); await runAdminImportWorkerOnce(provider);
    review = await current(review.item.id); const suggestion = review.item.suggestions[0];
    assert.equal(suggestion.baseline, 'Existing Album'); assert.equal(review.item.draft.album.title, 'Manual correction');
    await assert.rejects(adoptCatalogReview(String(actor), review.item.id, { ...mutation(review.item.revision), generation: 1, selectedIds: [suggestion.id], rejectIds: [] }), code('ADMIN_IMPORT_FIELD_CONFLICT'));
    review = await edit(review, draft => { draft.album.title = 'Existing Album'; });
    review = await adoptCatalogReview(String(actor), review.item.id, { ...mutation(review.item.revision), generation: 1, selectedIds: [suggestion.id], rejectIds: [] });
    assert.equal(review.item.draft.album.title, 'Proposed Album'); assert.equal((await db().collection('albums').findOne({ _id: album }))!.title, 'Existing Album');
});
test('explicit selected apply preserves unrelated metadata, Credits, assets, visibility and membership; receipt and order commit together', async () => {
    let review = await create(); const initialAlbum = await db().collection('albums').findOne({ _id: album }), initialTrack = await db().collection('audioTracks').findOne({ _id: first });
    review = await edit(review, draft => { draft.album.title = 'Approved Album'; draft.album.releaseDate = { year: 2024, month: 2, day: null }; draft.tracks[0].title = 'Approved Track'; draft.tracks[0].trackNumber = 3; draft.tracks[1].title = 'Unselected title'; });
    const fields: CatalogReviewField[] = [albumTitle, { scope: 'album', slotId: null, field: 'releaseDate' }, { scope: 'track', slotId: review.item.source.tracks[0].slotId, field: 'title' }, { scope: 'track', slotId: review.item.source.tracks[0].slotId, field: 'trackNumber' }];
    const body = { ...mutation(review.item.revision), fields }, result = await applyCatalogReview(String(actor), review.item.id, body);
    assert.equal(result.item.state, 'applied'); assert.equal(result.receipt!.kind, 'apply'); assert.equal(result.item.applied!.operationId, body.operationId);
    const updatedAlbum = await db().collection('albums').findOne({ _id: album }), updatedTrack = await db().collection('audioTracks').findOne({ _id: first });
    assert.equal(updatedAlbum!.title, 'Approved Album'); assert.deepEqual(updatedAlbum!.releaseDate, { year: 2024, month: 2 }); assert.deepEqual(updatedAlbum!.audioTrackIds, [String(second), String(first)]);
    for (const field of ['visibility', 'credits', 'attributionStatus', 'coverArtUrl', 'unrelated']) assert.deepEqual(updatedAlbum![field], initialAlbum![field]);
    for (const field of ['visibility', 's3Key', 'originalFileName', 'albumId', 'duration', 'unrelated']) assert.deepEqual(updatedTrack![field], initialTrack![field]);
    assert.equal(updatedTrack!.title, 'Approved Track'); assert.equal((await db().collection('audioTracks').findOne({ _id: second }))!.title, 'Track 2');
    assert.equal((await db().collection('artists').findOne({ _id: artist }))!.name, 'Existing Artist');
    assert.deepEqual(await applyCatalogReview(String(actor), review.item.id, body), result);
    await assert.rejects(applyCatalogReview(String(actor), review.item.id, { ...body, fields: [albumTitle] }), code('ADMIN_IMPORT_OPERATION_CONFLICT'));
    await assert.rejects(editCatalogReview(String(actor), review.item.id, { ...mutation(result.item.revision), draft: review.item.draft }), code('ADMIN_CATALOG_REVIEW_APPLIED'));
});
test('applying selected Track Numbers re-derives the Album order within Disc Numbers', async () => {
    // Track Number alone would put `second` (now 1) before `first` (now 5); disc 1 still precedes disc 2.
    await db().collection('audioTracks').updateOne({ _id: first }, { $set: { discNumber: 1, discNumberSource: 'embedded' } });
    await db().collection('audioTracks').updateOne({ _id: second }, { $set: { discNumber: 2, discNumberSource: 'embedded' } });
    let review = await create();
    review = await edit(review, draft => { draft.tracks[0].trackNumber = 5; draft.tracks[1].trackNumber = 1; });
    const fields: CatalogReviewField[] = review.item.source.tracks.map(track => ({ scope: 'track', slotId: track.slotId, field: 'trackNumber' }));
    const result = await applyCatalogReview(String(actor), review.item.id, { ...mutation(review.item.revision), fields });
    assert.equal(result.item.state, 'applied');
    assert.deepEqual((await db().collection('albums').findOne({ _id: album }))!.audioTrackIds, [String(first), String(second)]);
    const [firstTrack, secondTrack] = await Promise.all([first, second].map(id => db().collection('audioTracks').findOne({ _id: id })));
    assert.deepEqual([firstTrack!.trackNumber, firstTrack!.discNumber, secondTrack!.trackNumber, secondTrack!.discNumber], [5, 1, 1, 2]);
});
test('concurrent private edits have one winner; concurrent application from separate projects cannot overwrite the first', async () => {
    const a = await create(), b = await create();
    const edits = await Promise.allSettled([edit(a, draft => { draft.album.title = 'A'; }), edit(a, draft => { draft.album.title = 'B'; })]); assert.equal(edits.filter(value => value.status === 'fulfilled').length, 1);
    const firstReview = await current(a.item.id), secondReview = await edit(b, draft => { draft.album.title = 'Second project'; });
    const applications = await Promise.allSettled([apply(firstReview), apply(secondReview)]); assert.equal(applications.filter(value => value.status === 'fulfilled').length, 1);
    assert.equal(await importCollection().countDocuments({ catalogApplied: { $exists: true } }), 1);
});
test('late apply transaction failure rolls back prior Track updates, Disc Numbers, Album ordering and the review receipt', async () => {
    let review = await create(); review = await edit(review, draft => { draft.album.title = 'New'; draft.tracks[0].title = 'New track'; draft.tracks[0].discNumber = 3; });
    const originalCollection = db().collection.bind(db()), albumCollection = originalCollection('albums');
    (db() as any).collection = (name: string, ...args: any[]) => {
        if (name !== 'albums') return originalCollection(name, ...args);
        return new Proxy(albumCollection, { get(target, property) { if (property === 'updateOne') return async () => { throw new Error('Synthetic final write fault'); }; const value = (target as any)[property]; return typeof value === 'function' ? value.bind(target) : value; } });
    };
    const slotId = review.item.source.tracks[0].slotId;
    try { await assert.rejects(apply(review, [albumTitle, { scope: 'track', slotId, field: 'title' }, { scope: 'track', slotId, field: 'discNumber' }]), /Synthetic final write fault/); }
    finally { (db() as any).collection = originalCollection; }
    const track = await db().collection('audioTracks').findOne({ _id: first }), storedAlbum = await db().collection('albums').findOne({ _id: album });
    assert.equal(track!.title, 'Track 1'); assert.deepEqual(['discNumber' in track!, 'discNumberSource' in track!], [false, false]);
    assert.equal(storedAlbum!.title, 'Existing Album'); assert.deepEqual(storedAlbum!.audioTrackIds, [String(first), String(second)]);
    const remaining = await current(review.item.id); assert.equal(remaining.item.revision, review.item.revision); assert.equal(remaining.item.applied, null);
});
test('review/import share account admission and daily provider budgets; stopped in-flight work still occupies its slot', async () => {
    let review = await create(); review = await analyzeCatalogReview(String(actor), review.item.id, mutation(1), provider);
    const legacy = await createAdminImport(String(actor), { operationId: randomUUID(), manifest: { rootLabel: 'Folder', files: [{ slotId: randomUUID(), filename: 'Song.mp3', relativePath: 'Song.mp3', byteLength: 1 }] } });
    await assert.rejects(analyzeAdminImport(String(actor), legacy.item.id, mutation(1), provider), code('ADMIN_IMPORT_ACTOR_BUSY'));
    const entered = deferred(), release = deferred(); let calls = 0;
    const worker = runAdminImportWorkerOnce({ configured: () => true, analyze: async input => { calls++; assert.equal(input.purpose, 'catalogReview'); assert.equal(input.manifest.rootLabel, ''); entered.resolve(); await release.promise; return []; } });
    await entered.promise;
    try { review = await current(review.item.id); await cancelCatalogReviewAnalysis(String(actor), review.item.id, mutation(review.item.revision)); await assert.rejects(analyzeAdminImport(String(actor), legacy.item.id, mutation(1), provider), code('ADMIN_IMPORT_ACTOR_BUSY')); }
    finally { release.resolve(); await worker; }
    assert.equal(calls, 1); assert.equal((await current(review.item.id)).item.analysis.state, 'cancelled');
    await analyzeAdminImport(String(actor), legacy.item.id, mutation(1), provider);
    await db().collection('adminImportAnalysisSlots').updateOne({ _id: `daily:${new Date().toISOString().slice(0, 10)}` as any }, { $set: { attempts: ADMIN_IMPORT_LIMITS.dailyAttempts } });
    await runAdminImportWorkerOnce({ configured: () => true, analyze: async () => { calls++; return []; } });
    assert.equal(calls, 1); assert.equal((await getAdminImport(String(actor), legacy.item.id)).item.analysis.issue, 'budgetExhausted');
});
