/** Rewrites a review as one stored before Draft v2 reviews: no draftVersion, a v1 draft and baseline, a v1 Artist suggestion and no captured discs. */
async function downgrade(result: CatalogReviewResponse) {
    const _id = new ObjectId(result.item.id), saved = (await importCollection().findOne({ _id }))!, draft = saved.draft as CatalogReviewResponse['item']['draft'];
    const v1 = { album: { title: draft.album.title, artistName: 'Existing Artist', releaseDate: draft.album.releaseDate, visibility: draft.album.visibility }, tracks: draft.tracks.map(({ slotId, title, trackNumber }) => ({ slotId, title, trackNumber })) };
    const suggestion = { id: 'a'.repeat(24), generation: 1, scope: 'album', slotId: null, field: 'artistName', baseline: 'Existing Artist', value: 'Existing Artist (corrected)', source: 'context', evidence: 'Existing title', decision: 'pending' };
    await importCollection().updateOne({ _id }, { $unset: { draftVersion: '' }, $set: { draft: v1, 'catalogSource.tracks': saved.catalogSource!.tracks.map(({ discNumber: _disc, ...track }) => track), suggestions: [suggestion],
        analysis: { ...saved.analysis, state: 'complete', generation: 1, baseline: structuredClone(v1) } } } as any);
    return { _id, v1 };
}
test('a review stored before Draft v2 reviews opens converted, stays unconverted on reads, refusals and cancellation, and converts at its first change', async () => {
    const createdWith = await createBody(), a = await createCatalogReview(String(actor), createdWith), { _id, v1 } = await downgrade(a), id = a.item.id;
    const legacyEntry = { key: legacyArtistEntryKey(id), name: 'Existing Artist', role: 'primary', joinPhrase: null, musicBrainzId: null };
    const stored = await importCollection().findOne({ _id });
    // A create replay returns the stored review, shown converted.
    assert.deepEqual((await createCatalogReview(String(actor), createdWith)).item.draft.album.artists, [legacyEntry]);
    let review = await current(id);
    assert.deepEqual(review.item.draft.album, { title: 'Existing Album', artists: [legacyEntry], label: null, releaseDate: { year: 2020, month: null, day: null }, visibility: 'hidden' });
    assert.deepEqual(review.item.draft.tracks.map(track => track.discNumber), [null, null]);
    assert.equal(review.item.source.tracks.some(track => 'discNumber' in track), false);
    assert.deepEqual([review.item.suggestions[0].field, review.item.suggestions[0].baseline], ['artists', [legacyEntry]]);
    assert.equal(review.item.capabilities.apply, true);
    // A v1 save asks for a reload and a changed context is invalid; neither converts or writes anything.
    await assert.rejects(editCatalogReview(String(actor), id, { ...mutation(review.item.revision), draft: { ...v1, album: { ...v1.album, title: 'v1 save' } } }), code('ADMIN_IMPORT_RELOAD_REQUIRED'));
    const response = await request(`/catalog-reviews/${id}`, 'PATCH', { ...mutation(review.item.revision), draft: v1 });
    assert.equal(response.status, 409); assert.deepEqual(await response.json(), { code: 'ADMIN_IMPORT_RELOAD_REQUIRED' });
    await assert.rejects(edit(review, draft => { draft.album.artists = []; }), code('ADMIN_IMPORT_INVALID_INPUT'));
    await assert.rejects(adoptCatalogReview(String(actor), id, { ...mutation(review.item.revision), generation: 1, selectedIds: ['a'.repeat(24)], rejectIds: [] }), code('ADMIN_IMPORT_INVALID_INPUT'));
    assert.deepEqual(await importCollection().findOne({ _id }), stored);
    // Stopping analysis never converts.
    review = await cancelCatalogReviewAnalysis(String(actor), id, mutation(review.item.revision));
    let doc = await importCollection().findOne({ _id }); assert.deepEqual(['draftVersion' in doc!, doc!.draft], [false, v1]);
    // An uncaptured disc cannot be applied: no receipt and no catalog write.
    const albumBefore = await db().collection('albums').findOne({ _id: album }), tracksBefore = await db().collection('audioTracks').find({}).sort({ _id: 1 }).toArray();
    await assert.rejects(apply(review, [{ scope: 'track', slotId: review.item.source.tracks[0].slotId, field: 'discNumber' }]), code('ADMIN_IMPORT_INVALID_INPUT'));
    assert.deepEqual(await db().collection('albums').findOne({ _id: album }), albumBefore); assert.deepEqual(await db().collection('audioTracks').find({}).sort({ _id: 1 }).toArray(), tracksBefore);
    doc = await importCollection().findOne({ _id }); assert.deepEqual([doc!.revision, 'draftVersion' in doc!], [review.item.revision, false]);
    // An uncaptured disc cannot be saved either: invalid input, with no conversion and no write.
    const unconverted = await importCollection().findOne({ _id });
    await assert.rejects(edit(review, draft => { draft.album.title = 'Converted title'; draft.tracks[0].discNumber = 4; }), code('ADMIN_IMPORT_INVALID_INPUT'));
    assert.deepEqual(await importCollection().findOne({ _id }), unconverted);
    // The first admitted edit stores Draft v2: the legacy entry, its baseline and suggestion, no origins and an untouched source.
    review = await edit(review, draft => { draft.album.title = 'Converted title'; });
    doc = await importCollection().findOne({ _id });
    assert.equal(doc!.draftVersion, 2); assert.equal('draftOrigins' in doc!, false);
    assert.deepEqual((doc!.draft as typeof review.item.draft).album.artists, [legacyEntry]); assert.deepEqual((doc!.analysis.baseline as typeof review.item.draft).album.artists, [legacyEntry]);
    assert.deepEqual(doc!.suggestions.map(value => value.field), ['artists']); assert.deepEqual(doc!.catalogSource, stored!.catalogSource);
    assert.deepEqual(review.item.draft.tracks.map(track => track.discNumber), [null, null]);
    // A title still applies; an uncaptured disc never does.
    await assert.rejects(apply(review, [albumTitle, { scope: 'track', slotId: review.item.source.tracks[0].slotId, field: 'discNumber' }]), code('ADMIN_IMPORT_INVALID_INPUT'));
    review = await apply(review); assert.equal(review.item.state, 'applied');
    assert.equal((await db().collection('albums').findOne({ _id: album }))!.title, 'Converted title'); assert.equal('discNumber' in (await db().collection('audioTracks').findOne({ _id: first }))!, false);
    // Adopting on a v1 review converts it too.
    const b = await create(); await downgrade(b);
    const rejected = await adoptCatalogReview(String(actor), b.item.id, { ...mutation(b.item.revision), generation: 1, selectedIds: [], rejectIds: ['a'.repeat(24)] });
    assert.equal(rejected.item.suggestions[0].decision, 'rejected'); assert.equal((await importCollection().findOne({ _id: new ObjectId(b.item.id) }))!.draftVersion, 2);
    // An old applied review opens read-only.
    const { _id: appliedId } = await downgrade(review);
    const old = await current(review.item.id);
    assert.deepEqual([old.item.state, old.item.capabilities, old.item.applied!.fields], ['applied', { analysis: false, apply: false }, [albumTitle]]);
    await assert.rejects(edit(old, draft => { draft.album.title = 'After apply'; }), code('ADMIN_CATALOG_REVIEW_APPLIED'));
    const appliedDoc = await importCollection().findOne({ _id: appliedId });
    await assert.rejects(editCatalogReview(String(actor), review.item.id, { ...mutation(old.item.revision), draft: v1 }), code('ADMIN_IMPORT_RELOAD_REQUIRED'));
    assert.deepEqual(await importCollection().findOne({ _id: appliedId }), appliedDoc);
});

